&lt;td&gt;
&lt;a href="https://wingo-ui.com/components/number-input" rel="noopener noreferrer"&gt;Number Input&lt;/a&gt;, &lt;a href="https://wingo-ui.com/components/currency-input" rel="noopener noreferrer"&gt;Currency Input&lt;/a&gt; (Pro)&lt;/td&gt;
&lt;td&gt;Numeric or decimal keypad, 44px steppers or amount chips&lt;/td&gt;
&lt;/tr&gt;
